ability\", (\"hlr traceability\", \"traceability\"))]\n40\t\n41\tPRIORITY_ORDER = {\"P0\": 0, \"P1\": 1, \"P2\": 2}\n42\t\n43\tFRONTMATTER_RE = re.compile(r'^---\\s*\\n(.*?\\n)---\\s*\\n', re.DOTALL)\n44\t\n45\t\n46\tdef read_frontmatter(path):\n47\t    \"\"\"Return (frontmatter dict, body string) for a markdown file.\"\"\"\n48\t    with open(path, encoding=\"utf-8\") as f:\n49\t        content = f.read()\n50\t    m = FRONTMATTER_RE.match(content)\n51\t    if not m:\n52\t        return {}, content\n53\t    try:\n54\t        data = yaml.safe_load(m.group(1))\n55\t    except yaml.YAMLError:\n56\t        return {}, content\n57\t    if not isinstance(data, dict):\n58\t        return {}, content\n59\t    return data, content[m.end():]\n60\t\n61\t\n62\tdef body_headings(body):\n63\t    heads = []\n64\t    for hm in re.finditer(r'^#{1,6}\\s+(.+?)\\s*$', body, re.M):\n65\t        heads.append(re.sub(r'[^a-z ]', '', hm.group(1).lower()).strip())\n66\t    return heads\n67\t\n68\t\n69\tdef load_epics(artifacts_dir, strat_id):\n70\t    \"\"\"Return {epic_key: (path, frontmatter, body)} for one strategy's epics.\n71\t\n72\t    epic_key is the filename stem; branch files carry their BRANCH- prefix.\n73\t    \"\"\"\n74\t    task_dir = os.path.join(artifacts_dir, \"epic-tasks\")\n75\t    if not os.path.isdir(task_dir):\n76\t        return {}\n77\t    pat = re.compile(re.escape(strat_id) + r\"-(BRANCH-[A-Z]-)?(E\\d{3})\\.md$\")\n78\t    epics = {}\n79\t    for name in sorted(os.listdir(task_dir)):\n80\t        m = pat.match(name)\n81\t        if not m:\n82\t            continue\n83\t        path = os.path.join(task_dir, name)\n84\t        fm, body = read_frontmatter(path)\n85\t        epics[name[:-3]] = (path, fm, body)\n86\t    return epics\n87\t\n88\t\n89\tdef dependency_closure(start_key, deps):\n90\t    \"\"\"All epics reachable from start_key by following dependencies.\"\"\"\n91\t    seen, stack = set(), list(deps.get(start_key, []))\n92\t    while stack:\n93\t        n = stack