es)\"\n133\t                         % (name, comp.strip(), components_path))\n134\t        # collect graph facts\n135\t        dl = fm.get(\"dependencies\")\n136\t        deps[key] = [x for x in dl if isinstance(x, str)] \\\n137\t            if isinstance(dl, list) else []\n138\t        is_branch[key] = \"BRANCH-\" in key\n139\t        is_docs[key] = fm.get(\"implementation_type\") == \"docs-authoring\"\n140\t        is_impl[key] = fm.get(\"type\") == \"Implementation\"\n141\t        prio[key] = fm.get(\"priority\")\n142\t\n143\t    # 3. Rule 11 — docs-authoring blocked by every main-plan Implementation\n144\t    universe = [k for k in epics\n145\t                if is_impl[k] and not is_docs[k] and not is_branch[k]]\n146\t    for k in sorted(epics):\n147\t        if not is_docs[k]:\n148\t            continue\n149\t        cl = dependency_closure(k, deps)\n150\t        missing = sorted(e for e in universe if e != k and e not in cl)\n151\t        if missing:\n152\t            probs.append(\"Rule 11: docs-authoring %s is not blocked by every \"\n153\t                         \"Implementation epic — add %s to its dependency chain\"\n154\t                         % (k, \", \".join(missing)))\n155\t\n156\t    # 4. Priority inheritance — enablers of P0 work must be P0\n157\t    for k in sorted(epics):\n158\t        if is_branch[k] or is_docs[k]:\n159\t            continue\n160\t        if prio.get(k) != \"P0\":\n161\t            continue\n162\t        # every main-plan, non-docs epic in k's closure enables P0 work\n163\t        cl = dependency_closure(k, deps)\n164\t        for t in sorted(cl):\n165\t            if is_branch[t] or is_docs[t]:\n166\t                continue\n167\t            if PRIORITY_ORDER.get(prio.get(t), 9) > 0:\n168\t                probs.append(\"priority inheritance: %s (%s) blocks P0 epic %s \"\n169\t                             \"but is %s — raise it to P0 or restructure\"\n170\t                             % (t, prio.get(t), k, prio.get(t)))\n171\t    return probs\n172\t\n173\t\n174\t# ─── self-check ───────────────────────────────────────────────────────────────\n175\t\n176\tdef _self_check():\n177\t    \"\"\"Verify each check fires on a minimal bad fixture and passes a good one.\"\"\"\n178\t    import shutil\n179\t    import tempfile\n180\t\n181\t    tmp = tempfile.mkdtemp(prefix=\"validate-decomp-selfcheck-\")\n182\t    try:\n183\t        art = os.path.join(tmp, \"artifacts\", \"epic-tasks\")\n184\t        os.makedirs(art)\n185\t        comp = os.path.join(tmp, \"components.txt\")\n186\t        with open(comp, \"w\") as f:\n187\t            f.write(\"Dashboard\\nServing Runtimes\\n\")\n188\t\n189\t        def write(name, fm, body):\n190\t            with open(os.path.join(art, name), \"w\") as f:\n191\t                f.write(\"---\\n%s\\n---\\n%s\" % (fm, body))\n192\t\n193\t        good_body = (\"# T\\n## Description\\nd\\n## Scope\\ns\\n\"\n194\t                     \"## Acceptance Criteria\\na\\n## HLR Traceability\\nh\\n\")\n195\t        write(\"RHAISTRAT-9001-E001.md\",\n196\t              \"component: Dashboard\\ntype: Implementation\\npriority: P0\\n\"\n197\t              \"dependencies: []\\n\", good_body)\n198\t        write(\"RHAISTRAT-9001-E002.md\",\n199\t              \"component: Serving Runtimes\\ntype: Implementation\\n\"\n200\t              \"implementation_type: docs-authoring\\npriority: P2\\n\"\n201\t              \"dependencies: [RHAISTRAT-9001-E001]\\n\", good_body)\n202\t        assert check(\"RHAISTRAT-9001\", os.path.join(tmp, \"artifacts\"),\n203\t                     comp) == [], \"good fixture must pass cleanly\"\n204\t\n205\t        # bad fixture: missing Scope, bad component, Rule 11 gap, P0->P1 edge\n206\t        write(\"RHAISTRAT-9002-E001.md\",\n207\t              \"component: Model Serving Stack\\ntype: Implementation\\n\"\n208\t              \"priority: P0\\ndependencies: [RHAISTRAT-9002-E002]\\n\",\n209\t              \"# T\\n## Description\\nd\\n## Acceptance Criteria\\na\\n\"\n210\t              \"## HLR Traceability\\nh\\n\")\n211\t        write(\"RHAISTRAT-9002-E002.md\",\n212\t              \"component: Dashboard\\ntype: Implementation\\npriority: P1\\n\"\n213\t              \"dependencies: []\\n\", good_body)\n214\t        write(\"RHAISTRAT-9002-E003.md\",\n215\t              \"component: Dashboard\\ntype: Implementation\\n\"\n216\t              \"implementation_type: docs-authoring\\npriority: P2\\n\"\n217\t              \"dependencies: [RHAISTRAT-9002-E001]\\n\", good_body)\n218\t        # E004 is a main-plan Implementation the docs epic never depends on\n219\t        write(\"RHAISTRAT-9002-E004.md\",\n220\t              \"component: Dashboard\\ntype: Implementation\\npriority: P1\\n\"\n221\t              \"dependencies: []\\n\", good_body)\n222\t        probs = check(\"RHAISTRAT-9002\", os.path.join(tmp, \"artifacts\"), comp)\n223\t        joined = \"\\n\".join(probs)\n224\t        assert \"missing 'Scope'\" in joined, probs\n225\t        assert \"Model Serving Stack\" in joined, probs\n226\t        assert \"Rule 11\" in joined and \"E004\" in joined, probs\n227\t        assert \"priority inheritance\" in joined and \"E002\" in joined, probs\n228\t        print(\"self-check OK: 4 checks fire on bad fixture, clean on good\")\n229\t        return 0\n230\t    finally:\n231\t        shutil.rmtree(tmp, ignore_errors=True)\n232\t\n233\t\n234\tdef main(argv=None):\n235\t    ap = argparse.ArgumentParser(description=__doc__)\n236\t    ap.add_argument(\"strat_id\", nargs=\"?\", help=\"e.g. RHAISTRAT-9013\")\n237\t    ap.add_argument(\"--artifacts-dir\", default=\"artifacts\")\n238\t    ap.add_argument(\"--components\",\n239\t                    default=\".context/rhai-components.txt\")\n240\t    ap.add_argument(\"--self-check\", action=\"store_true\")\n241\t    args = ap.parse_args(argv)\n242\t\n243\t    if args.self_check:\n244\t        return _self_check()\n245\t    if not args.strat_id:\n246\t        ap.error(\"strat_id is required (unless --self-check)\")\n247\t\n248\t    probs = check(args.strat_id, args.artifacts_dir, args.components)\n249\t    if probs:\n250\t        for p in probs:\n251\t            print(\"VIOLATION: %s\" % p)\n252\t        print(\"%d violation(s) — fix these before marking the decomposition \"\n253\t              \"complete\" % len(probs))\n254\t        return 1\n255\t    print(\"OK: contract checks passed for %s\" % args.strat_id)\n256\t    return 0\n257\t\n258\t\n259\tif __name__ == \"__main__\":\n260\t    sys.exit(main())\n261\t"}]},"parent_tool_use_id":"chatcmpl-tool-ac712f216ff0358d","agent_id":"a4fb989e24f2e722c","session_id":"c024f609-bb75-4102-a6f5-d71433960ced","uuid":"bf271798-d4d3-40f8-aa11-f7c18cf74993","timestamp":"2026-10-22T04:16:42.706Z","tool_result_meta":[{"id":"chatcmpl-tool-ac3605da78fcd46a","permission_decision":{"decision":"accept","source":"config","reason_type":"mode"}}],"subagent_type":"claude","task_description":"Decompose RHAISTRAT-8010"}
